head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColIdByHeaderId]<br/>Header Column 의 ID 를 사용하여 매핑된 Body Column 의 ID 를 반환합니다.",
    "validation" : [
        "headerFilter 속성으로 표시되는 필터용 Header 는 매핑에서 제외되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성 (기본 데이터 바인딩)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // headerFilter 속성 적용 gridView 생성
    // headerFilter="true" + defaultShowHeaderFilter="true" 로 필터용 Header 행(filterColumn)을 표시한다.
    // 정상 Header : column1~column4 (Body col1~col4 와 매핑), 필터용 Header : filter1~filter4 (매핑 제외 대상)
    let grp_comp = $c.gcm.getTestGroup('');

    let strTarget = '';
    strTarget += '<w2:gridView ' + $c.gcm.strNameSpace + ' dataList="data:dlt_bind" headerFilter="true" defaultShowHeaderFilter="true" checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="rowFilter">';
    strTarget += '<w2:filterColumn width="70" style="" id="filterColumn1" value=""></w2:filterColumn>';
    strTarget += '<w2:filterColumn width="70" style="" id="filterColumn2" value=""></w2:filterColumn>';
    strTarget += '<w2:filterColumn width="70" style="" id="filterColumn3" value=""></w2:filterColumn>';
    strTarget += '<w2:filterColumn width="70" style="" id="filterColumn4" value=""></w2:filterColumn>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



scwin.btn_getColIdByHeaderId_onclick = function () {
    let headerId = par_headerId.getValue();

    let rtn = target1.getColIdByHeaderId(headerId);
    wf_body_bottom.getObj("scwin").setReturnValue("getColIdByHeaderId('" + headerId + "') : " + rtn);
}
